public class ClassLoaderDiagnosticDemo {
    public static void main(String[] args) {
        // Demonstrating ClassNotFoundException
        try {
            Class.forName("com.nonexistent.MyCustomClass");
        } catch (ClassNotFoundException e) {
            System.out.println("Caught explicit lookup failure: " + e.getMessage());
        }

        // Demonstrating NoClassDefFoundError scenario
        try {
            // If FaultyClass had a failing static initializer, or its dependency is missing
            loadMissingDependencyClass();
        } catch (NoClassDefFoundError e) {
            System.out.println("Caught implicit linkage failure: " + e.getMessage());
        }
    }

    private static void loadMissingDependencyClass() {
        // Simulating bytecode reference to a class whose dependency vanished at runtime
        System.out.println(MissingDependency.class.getName());
    }
}

class MissingDependency {}
